/**
 * Idiomorph - A standalone DOM morphing library.
 * This implementation provides high-performance DOM reconciliation,
 * matching nodes by ID and wire:key, maintaining scroll, focus, and selection,
 * and honoring wire:ignore directives.
 */
(function (global) {
    'use strict';

    const Idiomorph = {
        /**
         * Morphs oldNode to match newContent (HTML string or Element).
         * @param {Element} oldNode - The existing DOM node to morph
         * @param {string|Element} newContent - The new content to morph to
         * @param {Object} options - Morph options and callbacks
         * @returns {Element} The morphed oldNode
         */
        morph(oldNode, newContent, options = {}) {
            let newNode;
            if (typeof newContent === 'string') {
                const template = document.createElement('template');
                template.innerHTML = newContent;
                newNode = template.content.firstElementChild;
                if (!newNode) return oldNode;
            } else {
                newNode = newContent;
            }

            const callbacks = options.callbacks || {};

            // 1. Capture Focus & Selection
            const activeElement = document.activeElement;
            const activeElementId = activeElement && activeElement.id;
            const activeElementSelectionStart = activeElement ? activeElement.selectionStart : null;
            const activeElementSelectionEnd = activeElement ? activeElement.selectionEnd : null;

            // 2. Capture Scroll Positions
            const scrollPositions = new Map();
            function captureScroll(el) {
                if (el.nodeType === Node.ELEMENT_NODE && (el.scrollLeft > 0 || el.scrollTop > 0)) {
                    scrollPositions.set(el.id || el, { left: el.scrollLeft, top: el.scrollTop });
                }
                if (el.childNodes) {
                    el.childNodes.forEach(captureScroll);
                }
            }
            captureScroll(oldNode);

            // 3. Core Sync Logic
            function syncNode(oldEl, newEl) {
                if (!oldEl || !newEl) return;

                // Fire beforeNodeMorphed callback
                if (callbacks.beforeNodeMorphed && callbacks.beforeNodeMorphed(oldEl, newEl) === false) {
                    return; // Skip this node
                }

                // Handle wire:ignore (skip entire subtree)
                if (oldEl.nodeType === Node.ELEMENT_NODE && oldEl.hasAttribute('wire:ignore')) {
                    return;
                }

                // Sync text nodes
                if (oldEl.nodeType === Node.TEXT_NODE && newEl.nodeType === Node.TEXT_NODE) {
                    if (oldEl.nodeValue !== newEl.nodeValue) {
                        oldEl.nodeValue = newEl.nodeValue;
                    }
                    return;
                }

                // Sync element nodes
                if (oldEl.nodeType === Node.ELEMENT_NODE && newEl.nodeType === Node.ELEMENT_NODE) {
                    // Handle wire:ignore.self (skip syncing attributes and tag of self, but sync children)
                    const skipSelf = oldEl.hasAttribute('wire:ignore.self');
                    
                    if (!skipSelf) {
                        syncAttributes(oldEl, newEl);
                    }
                    
                    syncChildren(oldEl, newEl);
                }
            }

            function syncAttributes(oldEl, newEl) {
                const oldAttrs = oldEl.attributes;
                const newAttrs = newEl.attributes;

                // Remove old attributes
                for (let i = oldAttrs.length - 1; i >= 0; i--) {
                    const attrName = oldAttrs[i].name;
                    if (!newEl.hasAttribute(attrName)) {
                        oldEl.removeAttribute(attrName);
                    }
                }

                // Set/Update new attributes
                for (let i = 0; i < newAttrs.length; i++) {
                    const attrName = newAttrs[i].name;
                    const attrValue = newAttrs[i].value;
                    if (oldEl.getAttribute(attrName) !== attrValue) {
                        oldEl.setAttribute(attrName, attrValue);
                    }
                }

                // Sync input values correctly (DOM properties vs attributes)
                const tag = oldEl.tagName;
                if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') {
                    if (oldEl.type !== 'file') {
                        if (oldEl.value !== newEl.value) {
                            oldEl.value = newEl.value;
                        }
                    }
                    if (oldEl.type === 'checkbox' || oldEl.type === 'radio') {
                        if (oldEl.checked !== newEl.checked) {
                            oldEl.checked = newEl.checked;
                        }
                    }
                }
            }

            function syncChildren(oldEl, newEl) {
                const oldChildren = Array.from(oldEl.childNodes);
                const newChildren = Array.from(newEl.childNodes);
                
                let oldIndex = 0;
                let newIndex = 0;

                while (oldIndex < oldChildren.length || newIndex < newChildren.length) {
                    let oldChild = oldChildren[oldIndex];
                    let newChild = newChildren[newIndex];
                    
                    if (!oldChild) {
                        // Old is exhausted, append remaining new nodes
                        oldEl.appendChild(newChild.cloneNode(true));
                        newIndex++;
                    } else if (!newChild) {
                        // New is exhausted, remove remaining old nodes
                        oldEl.removeChild(oldChild);
                        oldIndex++;
                    } else {
                        const oldKey = getKey(oldChild);
                        const newKey = getKey(newChild);
                        
                        // List reconciliation based on keys
                        if (oldKey && oldKey !== newKey) {
                            const nextOldIndex = findKeyIndex(oldChildren, newKey, oldIndex + 1);
                            if (nextOldIndex !== -1) {
                                // Matching node found later in old list, move it here
                                const movedChild = oldChildren[nextOldIndex];
                                oldEl.insertBefore(movedChild, oldChild);
                                syncNode(movedChild, newChild);
                                // Remove the moved element from its original position in the tracking array
                                oldChildren.splice(nextOldIndex, 1);
                            } else {
                                // No matching key found, insert new node
                                oldEl.insertBefore(newChild.cloneNode(true), oldChild);
                                oldChildren.splice(oldIndex, 0, newChild);
                            }
                            oldIndex++;
                            newIndex++;
                        } else if (isSameNodeType(oldChild, newChild)) {
                            // Same tag or same key, sync them
                            syncNode(oldChild, newChild);
                            oldIndex++;
                            newIndex++;
                        } else {
                            // Different node types entirely, replace
                            oldEl.replaceChild(newChild.cloneNode(true), oldChild);
                            oldIndex++;
                            newIndex++;
                        }
                    }
                }
            }
            
            function findKeyIndex(nodes, key, startIndex) {
                for (let i = startIndex; i < nodes.length; i++) {
                    if (getKey(nodes[i]) === key) return i;
                }
                return -1;
            }

            function getKey(node) {
                if (node.nodeType === Node.ELEMENT_NODE) {
                    return node.getAttribute('wire:key') || node.id;
                }
                return null;
            }

            function isSameNodeType(oldNode, newNode) {
                if (oldNode.nodeType !== newNode.nodeType) return false;
                if (oldNode.nodeType === Node.ELEMENT_NODE) {
                    return oldNode.tagName === newNode.tagName;
                }
                return true;
            }

            // Start morphing
            syncNode(oldNode, newNode);

            // 4. Restore Scroll Positions
            function restoreScroll(el) {
                if (el.nodeType === Node.ELEMENT_NODE) {
                    const pos = scrollPositions.get(el.id || el);
                    if (pos) {
                        el.scrollLeft = pos.left;
                        el.scrollTop = pos.top;
                    }
                }
                if (el.childNodes) {
                    el.childNodes.forEach(restoreScroll);
                }
            }
            restoreScroll(oldNode);

            // 5. Restore Focus & Selection
            if (activeElementId) {
                const elemToFocus = document.getElementById(activeElementId);
                if (elemToFocus) {
                    elemToFocus.focus();
                    if (activeElementSelectionStart !== null && elemToFocus.setSelectionRange) {
                        try {
                            elemToFocus.setSelectionRange(activeElementSelectionStart, activeElementSelectionEnd);
                        } catch (e) {
                            // Ignored (not all input types support selection)
                        }
                    }
                }
            }

            return oldNode;
        }
    };

    // Expose on global window object
    global.Idiomorph = Idiomorph;
})(window);
